window.MOTIF_CATALOG_CHUNKS[73]={"cards":[{"id":"MEJE-KW-007416","row_version":1,"title":"음악으로 작동하는 기술","original":"Disco Tech","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"장치가 음악의 연주나 소리에 반응해 켜지거나 힘을 얻는다. 소리가 장식이 아니라 기술의 작동 조건이 된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-007416/index.html"},{"id":"MEJE-KW-007417","row_version":1,"title":"할인 혜택을 얻는 조건","original":"Discount Card","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 물건이나 능력, 특정 사건으로 인해 상점 물품을 더 낮은 값에 살 수 있게 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-007417/index.html"},{"id":"MEJE-KW-007418","row_version":1,"title":"동성 관계를 우회하는 비인간 설정","original":"Discount Lesbians","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"동성 간의 친밀함을 보여 주면서도 한 인물을 외계인이나 인간과 다른 존재로 설정해 현실의 성소수자 관계로 인정하지 않으려는 표현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007418/index.html"},{"id":"MEJE-KW-007419","row_version":2,"title":"꺼림칙한 외양으로 숨기기","original":"Discouraging Concealment","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"물건이나 버튼, 장소를 더럽거나 다가가기 꺼림칙해 보이도록 꾸며 사람들의 눈길과 접근을 피하게 하는 계략. 감추는 대상이 눈앞에 있어도 발견되지 않는 이유가 된다. 더러운 공중화장실처럼 사람들이 접근을 피하는 장소는 비밀 입구를 감추는 배경으로 쓰일 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007419/index.html"},{"id":"MEJE-KW-007420","row_version":1,"title":"자기 시신을 발견하기","original":"Discovering Your Own Dead Body","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"자신이 이미 죽었음을 모르던 인물이 자기 시신을 보고 과거의 사건과 현재 상태를 깨닫는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007420/index.html"},{"id":"MEJE-KW-007421","row_version":3,"title":"유행이 지나 진부해진 밈","original":"Discredited Meme","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"한때 널리 쓰이던 농담이나 유행어가 너무 많이 반복되어 더는 새롭거나 재치 있게 받아들여지지 않는다. 더는 진지하게 쓰기 어려운 클리셰은 서사 관습에, 유행이 지난 밈은 반복된 농담에 적용되는 비슷한 수용 변화다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-007421/index.html"},{"id":"MEJE-KW-007422","row_version":2,"title":"더는 진지하게 쓰기 어려운 클리셰","original":"Discredited Trope","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"반복과 시대 변화로 의미가 닳은 서사 관습이 원래의 효과를 잃고 패러디의 대상이 된다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007422/index.html"},{"id":"MEJE-KW-007423","row_version":2,"title":"먹기 싫은 음식을 몰래 버리기","original":"Discreet Dining Disposal","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대의 기분이나 의심을 피하려 음식은 먹은 척하면서 보이지 않는 곳에 처분한다. 마시기 싫은 음료를 몰래 버리기처럼 거절하기 어려운 권유를 받은 인물이 먹거나 마신 척하며 곤란을 피한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007423/index.html"},{"id":"MEJE-KW-007424","row_version":2,"title":"마시기 싫은 음료를 몰래 버리기","original":"Discreet Drink Disposal","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"권유받은 음료를 거절하기 어려운 인물이 마신 척하면서 따로 버려 불편하거나 위험한 상황을 피한다. 먹기 싫은 음식을 몰래 버리기의 음식 대신 음료가 문제일 때 같은 대인관계의 눈치가 작동한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007424/index.html"},{"id":"MEJE-KW-007425","row_version":1,"title":"보여 주지 않고 암시하는 장면","original":"Discretion Shot","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"사건이 일어나는 순간을 화면 밖에 두고 전후의 반응이나 결과로 관객이 짐작하게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007425/index.html"},{"id":"MEJE-KW-007426","row_version":1,"title":"편견을 예상하게 한 뒤 이유 바꾸기","original":"Discriminate and Switch","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물의 말이 차별적 이유로 이어질 듯하다가 전혀 다른 이유가 드러나며 청자의 예상을 뒤집는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007426/index.html"},{"id":"MEJE-KW-007427","row_version":1,"title":"작품 속에서 클리셰를 논하기","original":"Discussed Trope","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"인물이 자신이 속한 이야기에서 익숙한 장면 규칙을 알아보고 말로 다룬다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007427/index.html"},{"id":"MEJE-KW-007428","row_version":1,"title":"병과 고통으로 하얘진 머리","original":"Disease Bleach","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"오랜 질병이나 극심한 고통의 흔적을 갑자기 희어진 머리카락으로 표현한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-007428/index.html"},{"id":"MEJE-KW-007429","row_version":1,"title":"이름 없이 드러나는 질병","original":"Disease by Any Other Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품 속 인물은 병의 정체를 모르거나 다른 이름으로 부르지만 관객은 묘사된 징후로 무엇인지 알아챈다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007429/index.html"},{"id":"MEJE-KW-007430","row_version":1,"title":"병명을 사람 이름으로 쓰기","original":"Diseased Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"불쾌한 질병의 이름을 멀쩡한 인물의 이름에 붙여 어감과 뜻의 부조화로 웃음을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007430/index.html"},{"id":"MEJE-KW-007431","row_version":1,"title":"질병이 열어 주는 초능력 가능성","original":"Disease Imparts Empowering Potential","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"특정 질병을 겪은 경험이 초능력 발현에 필요한 조건 중 하나로 작동한다. 병을 앓았다는 사실만으로 힘이 생기는 것은 아니다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-007431/index.html"},{"id":"MEJE-KW-007432","row_version":1,"title":"질병 예방을 가르치는 교훈","original":"Disease-Prevention Aesop","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품이 감염을 피하고 다른 사람에게 옮기지 않도록 행동하자는 메시지를 이야기의 교훈으로 삼는다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-007432/index.html"},{"id":"MEJE-KW-007433","row_version":1,"title":"머리에서 떨어져 떠 있는 눈썹","original":"Disembodied Eyebrows","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"만화나 애니메이션에서 눈썹을 얼굴 윤곽 밖에 그려 감정 표현을 더 눈에 띄게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007433/index.html"},{"id":"MEJE-KW-007434","row_version":1,"title":"공포물임을 숨긴 이야기","original":"Disguised Horror Story","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"처음에는 다른 장르처럼 보이던 작품이 진행 중에 공포물의 본색을 드러내 관객의 방심을 이용한다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-007434/index.html"},{"id":"MEJE-KW-007435","row_version":1,"title":"인질을 적처럼 보이게 하기","original":"Disguised Hostage Gambit","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"악역이 인질의 옷이나 모습에 손을 대 구조하러 온 이들이 적과 인질을 헷갈리게 만든다. 오인에서 생기는 비극적 긴장이 핵심이다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007435/index.html"},{"id":"MEJE-KW-007436","row_version":1,"title":"다른 성별로 변장하기","original":"Disguised in Drag","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 신원을 감추거나 역할을 수행하려 평소와 다른 성별의 옷차림을 한다. 변장의 목적과 주변의 인식이 전개를 이끈다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007436/index.html"},{"id":"MEJE-KW-007437","row_version":2,"title":"더러운 공중화장실","original":"Disgusting Public Toilet","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"급히 찾아 들어간 공중화장실이 몹시 불결해 인물이 곤란해지는 배경이다. 불결한 장소를 사람들이 꺼린다는 점을 이용하면 꺼림칙한 외양으로 숨기기가 성립한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-007437/index.html"},{"id":"MEJE-KW-007438","row_version":1,"title":"채식 음식을 맛없게 그리기","original":"Disgusting Vegetarian Food","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 채식 식단을 단조롭고 불쾌한 음식으로만 묘사해 채식의 실제 다양성을 지우는 고정관념이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007438/index.html"},{"id":"MEJE-KW-007439","row_version":1,"title":"떨어지는 그릇을 받아내기","original":"Dish Dash","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 사방에서 떨어지는 접시를 바쁘게 받아내며 소동이 커지는 희극 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007439/index.html"},{"id":"MEJE-KW-007440","row_version":1,"title":"대지 조종 능력","original":"Dishing Out Dirt","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"흙과 바위, 지면을 움직여 길을 만들거나 장애물과 공격을 만드는 초자연적 힘이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-007440/index.html"},{"id":"MEJE-KW-007441","row_version":1,"title":"장례를 거부당한 죽은 자","original":"Dishonored Dead","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"생전의 죄나 금기를 이유로 고인이 통상적인 장례 의례를 받지 못한다. 죽은 뒤에도 공동체의 판단이 이어진다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-007441/index.html"},{"id":"MEJE-KW-007442","row_version":1,"title":"상속에서 배제된 자녀","original":"Disinherited Child","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"부모가 자녀를 유산의 수혜자에서 빼면서 가족 관계의 단절이나 갈등이 드러난다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007442/index.html"},{"id":"MEJE-KW-007443","row_version":2,"title":"소멸 처형실","original":"Disintegration Chamber","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"사람을 흔적 없이 없애는 방이나 기계가 처형의 공간으로 쓰이는 공상과학 설정이다. 소멸 광선을 방 안에 설치하면 소멸 자체가 공간의 처형 기능이 된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-007443/index.html"},{"id":"MEJE-KW-007444","row_version":2,"title":"소멸 광선","original":"Disintegrator Ray","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"맞은 대상을 먼지로 만들거나 완전히 사라지게 하는 허구의 광선 무기다. 소멸 처형실은 소멸 광선이 쓰이는 장소를 하나의 장치로 만든 형태다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-007444/index.html"},{"id":"MEJE-KW-007445","row_version":1,"title":"새 동료를 싫어하는 팀원","original":"Dislikes the New Guy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"기존 구성원 가운데 한 사람이 새로 들어온 동료를 경계하거나 못마땅하게 여겨 팀의 화합을 어렵게 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007445/index.html"},{"id":"MEJE-KW-007446","row_version":1,"title":"화려한 무기를 꺼리는 인물","original":"Dislikes the Shiny Weapon","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"눈에 띄는 특별한 무기보다 평범하고 믿을 만한 도구를 선호해 과시보다 실용을 택한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007446/index.html"},{"id":"MEJE-KW-007447","row_version":1,"title":"조각난 핵심 물건 찾기","original":"Dismantled MacGuffin","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"이야기에서 필요한 물건이 여러 조각으로 나뉘어 각지에 흩어져 있어 하나씩 모아야 한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007447/index.html"},{"id":"MEJE-KW-007448","row_version":3,"title":"사망 후 시신을 분리하는 사건","original":"Dismembering the Body","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사망한 인물의 시신을 의도적으로 분리하는 사건. 은폐나 처벌, 분노 등 서로 다른 동기를 드러내는 서사 장치로 쓰인다. 시신 처리의 곤란에서 시신을 훼손하는 행위가 은폐 방법의 하나로 등장할 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007448/index.html"},{"id":"MEJE-KW-007449","row_version":1,"title":"신체 절단의 결과를 가볍게 다루기","original":"Dismemberment Is Cheap","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 팔다리를 잃은 인물이 겪을 변화와 회복의 어려움을 생략하고 손실을 곧바로 넘어간다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007449/index.html"},{"id":"MEJE-KW-007450","row_version":1,"title":"칭찬을 흘려듣기","original":"Dismissing a Compliment","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"칭찬받은 인물이 그 말을 과장이나 빈말로 돌려 받아들이지 않는 대화 방식이다. 진심을 알아도 부끄러워서 그렇게 반응할 수 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007450/index.html"},{"id":"MEJE-KW-007451","row_version":1,"title":"발로 툭 차며 경멸하기","original":"Dismissive Kick","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 사람이나 물건을 발로 가볍게 차서 상대를 깔보거나 귀찮게 여기는 태도를 보인다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007451/index.html"},{"id":"MEJE-KW-007452","row_version":1,"title":"실패를 피하려 목표도 피하기","original":"Dismotivation","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"실패하거나 실망할 가능성이 두려워 바라는 목표를 향한 행동 자체를 미룬다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007452/index.html"},{"id":"MEJE-KW-007453","row_version":2,"title":"노래 속의 추상적 애니메이션","original":"Disney Acid Sequence","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"뮤지컬 장면에서 화면이 이야기 속 사건의 재현을 벗어나 음악의 감각과 정서를 추상적 이미지로 펼친다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007453/index.html"},{"id":"MEJE-KW-007454","row_version":1,"title":"숲속 동물 도움 장면의 패러디","original":"Disney Creatures of the Farce","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"온화한 인물 곁에 동물들이 몰려와 노래하거나 집안일을 돕는 익숙한 장면을 비틀어 예상 밖의 결과나 반응으로 웃음을 만드는 표현 관습.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007454/index.html"},{"id":"MEJE-KW-007455","row_version":2,"title":"죽은 줄 알았던 주요 인물의 귀환","original":"Disney Death","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이야기 끝무렵 중요 인물이 죽은 듯 보여 슬픔을 일으키지만 곧 살아 있음이 밝혀진다. 추락하는 악역의 결말에서는 악역이 추락해 퇴장하지만 주요 인물의 가짜 죽음은 다시 돌아올 여지를 남긴다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007455/index.html"},{"id":"MEJE-KW-007456","row_version":2,"title":"디즈니풍 그림체","original":"Disneyesque","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"디즈니 애니메이션으로 인식되는 부드러운 선과 표정 등을 다른 작품이 차용해 친숙한 인상을 만든다. 과장된 몸짓의 애니메이션 연기은 그림체뿐 아니라 몸짓과 표정을 크게 쓰는 연기 방식에서도 연상될 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-007456/index.html"},{"id":"MEJE-KW-007457","row_version":1,"title":"거친 이야기를 가족용으로 순화하기","original":"Disneyfication","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"오래된 이야기의 잔혹하거나 불편한 요소를 덜어 내 어린 관객에게 맞는 밝은 이야기로 바꾼다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007457/index.html"},{"id":"MEJE-KW-007458","row_version":1,"title":"선물로만 가까워지는 부모","original":"Disneyland Dad","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"함께 보내는 시간은 적지만 비싼 선물과 화려한 나들이로 애정을 보상하려는 부모의 모습이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007458/index.html"},{"id":"MEJE-KW-007459","row_version":1,"title":"무엇이든 소유권을 주장하는 기업","original":"Disney Owns This Trope","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"허구의 거대 기업이 평범한 말이나 자연 현상까지 자기 소유라고 주장하며 권리의 범위를 터무니없이 넓힌다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007459/index.html"},{"id":"MEJE-KW-007460","row_version":2,"title":"과장된 몸짓의 애니메이션 연기","original":"Disney School of Acting and Mime","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 감정을 손짓과 표정으로 크게 표현해 무성극처럼 행동하는 애니메이션의 연기 관습이다. 과장된 몸짓은 디즈니풍 그림체로 인식되는 화면의 인물 표현을 이루기도 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007460/index.html"},{"id":"MEJE-KW-007461","row_version":1,"title":"추락하는 악역의 결말","original":"Disney Villain Death","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"영웅이 직접 죽이지 않아도 악역이 마지막 대결에서 높은 곳에서 떨어져 퇴장하는 결말 관습이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007461/index.html"},{"id":"MEJE-KW-007462","row_version":2,"title":"명령을 어겨도 처벌받지 않기","original":"Disobeyed Orders, Not Punished","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상관의 지시를 거스른 인물이 결과나 사정 때문에 처벌을 면하며 복종과 판단의 충돌이 드러난다. 권위를 의심하라는 권위의 메시지가 요구하는 독립적 판단은 명령 위반의 평가를 바꿀 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007462/index.html"},{"id":"MEJE-KW-007463","row_version":1,"title":"권위를 의심하라는 권위의 메시지","original":"Disobey This Message","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품이 권위가 전하는 말을 그대로 믿지 말라고 가르치면서 그 교훈 자체는 믿어 달라고 요구하는 역설이다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-007463/index.html"},{"id":"MEJE-KW-007464","row_version":1,"title":"번호가 엉킨 발표","original":"Disorganized Outline Speech","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"차례를 붙여 설명하던 인물이 순서를 헷갈리거나 같은 항목을 반복해 발표의 조직성이 무너진다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007464/index.html"},{"id":"MEJE-KW-007465","row_version":1,"title":"원작자가 부인한 각색판","original":"Disowned Adaptation","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"원작자가 마음에 들지 않는 각색 작품과 자신의 관계를 공개적으로 부정한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007465/index.html"},{"id":"MEJE-KW-007466","row_version":2,"title":"부모와의 관계를 끊는 자녀","original":"Disowned Parent","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"자녀가 부모의 행동이나 오랜 갈등을 이유로 가족 관계를 더는 인정하지 않겠다고 선언한다. 형제자매 관계 끊기는 절연의 대상이 부모가 아니라 형제자매일 때 나타나는 관계 단절이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007466/index.html"},{"id":"MEJE-KW-007467","row_version":2,"title":"형제자매 관계 끊기","original":"Disowned Sibling","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물이 형제자매 사이의 유대를 부정하고 더는 가족으로 대하지 않겠다고 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007467/index.html"},{"id":"MEJE-KW-007468","row_version":1,"title":"인사말은 생략하자","original":"Dispense with the Pleasantries","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"형식적인 안부나 칭찬을 끊고 중요한 본론부터 말하자고 요구하는 대사다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007468/index.html"},{"id":"MEJE-KW-007469","row_version":1,"title":"후대 작품이 가린 첫 등장","original":"Displaced Origin","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"인물이 처음 나온 작품보다 뒤의 속편이나 각색판이 더 유명해져 원래의 출발점이 잘 떠오르지 않게 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007469/index.html"},{"id":"MEJE-KW-007470","row_version":1,"title":"소모용 분신","original":"Disposable Decoy Doppelgänger","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 전투 중 잠깐 쓸 분신을 만들어 적의 공격과 시선을 대신 받게 한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-007470/index.html"},{"id":"MEJE-KW-007471","row_version":3,"title":"곧 사라질 약혼 상대","original":"Disposable Fiancé","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"연애 서사에서 주인공의 결합을 가로막던 약혼자가 쉽게 정리될 인물로 설정되어 참된 연인의 장애물만 맡는다. 속편에서 사라진 연인과 달리 곧 사라질 약혼 상대는 처음부터 주인공 연애의 장애물로 배치된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007471/index.html"},{"id":"MEJE-KW-007472","row_version":1,"title":"소모품처럼 취급되는 인턴","original":"Disposable Intern","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"조직의 낮은 지위에 놓인 인턴이 위험이나 부당한 대우를 떠맡으며 쉽게 대체 가능한 사람처럼 그려진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007472/index.html"},{"id":"MEJE-KW-007473","row_version":1,"title":"속편에서 사라진 연인","original":"Disposable Love Interest","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"전편에서 연인이었던 인물이 속편에서 사라졌지만 작품은 관계가 끝난 경위를 설명하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007473/index.html"},{"id":"MEJE-KW-007474","row_version":2,"title":"먼저 희생되는 운전 담당","original":"Disposable Pilot","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"주인공 일행을 태운 항공기나 차량의 운전자가 사고와 공격에서 먼저 희생되어 이동의 안전이 무너진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007474/index.html"},{"id":"MEJE-KW-007475","row_version":3,"title":"소모되는 성 노동자 인물","original":"Disposable Sex Worker","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"성 노동자 인물이 주로 악역의 잔혹성을 보여 주기 위한 피해자로 등장하고 자신의 삶은 충분히 다뤄지지 않는다. 남성 인물의 동기로만 죽는 여성은 성 노동자 인물의 죽음을 다른 인물의 분노와 서사 진전에만 쓰는 방식으로 나타날 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007475/index.html"},{"id":"MEJE-KW-007476","row_version":1,"title":"초능력의 근원을 없애기","original":"Disposable Superhero Maker","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"자신과 같은 힘을 지닌 인물이 다시 나오지 못하도록 능력을 만들어 내는 물건이나 원천을 없앤다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007476/index.html"},{"id":"MEJE-KW-007477","row_version":1,"title":"소모품처럼 취급되는 주거 취약자","original":"Disposable Vagrant","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사회적 보호가 약한 주거 취약자가 실종되거나 희생되어도 주변 인물들이 대수롭지 않게 여기는 묘사다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007477/index.html"},{"id":"MEJE-KW-007478","row_version":2,"title":"떼어 버릴 수 있는 탈것 부분","original":"Disposable Vehicle Section","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"차량이나 우주선의 손상된 일부를 분리해 남은 부분만 계속 움직이게 만든다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-007478/index.html"},{"id":"MEJE-KW-007479","row_version":3,"title":"남성 인물의 동기로만 죽는 여성","original":"Disposable Woman","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여성 인물이 자신의 이야기보다 남성 인물의 성장·복수·슬픔을 촉발하기 위해 죽는 서사 관습이다. 소모되는 성 노동자 인물은 여성 인물의 죽음을 성 노동자의 사회적 지위와 결합한 표현일 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007479/index.html"},{"id":"MEJE-KW-007480","row_version":1,"title":"시신 처리의 곤란","original":"Disposing of a Body","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"사망 사건 뒤 시신이 남아 인물이 비밀 유지와 사건의 결과를 마주하게 된다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-007480/index.html"},{"id":"MEJE-KW-007481","row_version":2,"title":"작은 성취에 지나친 환호","original":"Disproportionate Celebration","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사소한 성공을 거대한 승리처럼 축하해 주변의 반응과 성취의 실제 크기 사이에서 웃음을 만든다. 작은 호의에 과도한 보답은 작은 호의에 주는 보답이고, 과한 축하는 자기 성취를 크게 여기는 반응이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007481/index.html"},{"id":"MEJE-KW-007482","row_version":2,"title":"턱없이 부족한 배상","original":"Disproportionate Restitution","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"큰 잘못을 저지른 인물이 피해에 한참 못 미치는 작은 선물이나 사과를 내놓고 충분한 보상이라고 여긴다. 작은 호의에 과도한 보답은 보답의 크기를 지나치게 키우지만 부족한 배상은 갚아야 할 책임을 지나치게 줄인다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007482/index.html"},{"id":"MEJE-KW-007483","row_version":2,"title":"사소한 일에 과도한 보복","original":"Disproportionate Retribution","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"받은 해에 비해 터무니없이 큰 벌이나 복수를 가해 상대와 주변에 더 큰 피해를 낳는다. 턱없이 부족한 배상과 달리 과도한 보복은 상대에게 주는 피해가 원래 잘못보다 훨씬 크다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007483/index.html"},{"id":"MEJE-KW-007484","row_version":1,"title":"작은 호의에 과도한 보답","original":"Disproportionate Reward","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가벼운 도움을 받은 인물이 평생의 은혜처럼 여겨 지나치게 큰 선물이나 헌신으로 갚는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007484/index.html"},{"id":"MEJE-KW-007485","row_version":1,"title":"실격 덕분에 얻은 승리","original":"Disqualification-Induced Victory","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"경기에서 앞선 참가자가 규정 위반으로 탈락해 뒤에 있던 인물이 승자로 올라선다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007485/index.html"},{"id":"MEJE-KW-007486","row_version":1,"title":"취소된 발언의 잔상","original":"Disregard That Statement","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"재판에서 부적절한 말이 나온 뒤 판사가 무시하라고 지시해도 배심원의 기억에는 그 말이 남는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007486/index.html"},{"id":"MEJE-KW-007487","row_version":2,"title":"가구 위에 발을 올리는 무례","original":"Disrespectful Feet on Furniture","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 책상이나 의자 위에 발을 올려놓아 주변 사람을 무시하거나 규칙을 얕보는 태도를 보인다. 발로 툭 차며 경멸하기처럼 가구 위에 발을 올리는 행동도 말없이 경멸을 드러낸다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007487/index.html"},{"id":"MEJE-KW-007488","row_version":1,"title":"영화관 관람 방해","original":"Disrupting the Theater","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"극장에서 떠들거나 화면을 가리는 행동으로 다른 관객의 관람을 방해하는 상황이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007488/index.html"},{"id":"MEJE-KW-007489","row_version":1,"title":"가족 생활에 불만인 가장","original":"Dissatisfied Family Man","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"결혼과 자녀가 있는 삶을 이루었지만 기대했던 행복을 느끼지 못하고 가족의 책임을 짐처럼 여기는 인물이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007489/index.html"},{"id":"MEJE-KW-007490","row_version":1,"title":"다툰 뒤 찾아오는 후회","original":"Dissension Remorse","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"동료끼리의 말다툼이나 싸움이 끝난 뒤 공통 목표를 해쳤다는 사실을 깨닫고 관계를 돌아본다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007490/index.html"},{"id":"MEJE-KW-007491","row_version":1,"title":"닮았다고 해 놓고 차이만 말하기","original":"Dissimile","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"두 대상을 비슷하다고 소개한 뒤 다른 점을 줄줄이 말해 처음의 비유를 스스로 무너뜨리는 말장난이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007491/index.html"},{"id":"MEJE-KW-007492","row_version":1,"title":"화면 겹침 전환","original":"Dissolve","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"앞 장면이 천천히 사라지는 동안 다음 장면이 겹쳐 나타나 시간과 장소의 변화를 잇는 영상 전환이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007492/index.html"},{"id":"MEJE-KW-007493","row_version":2,"title":"상황에 맞지 않는 웃음","original":"Dissonant Laughter","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"위험하거나 슬픈 상황에서 한 인물만 웃어 주변의 감정과 어긋나는 불안을 만든다. 참혹한 상황 속 평온은 같은 참혹한 상황에서 웃음 대신 차분한 표정으로 주변 정서와 어긋난다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-007493/index.html"},{"id":"MEJE-KW-007494","row_version":1,"title":"참혹한 상황 속 평온","original":"Dissonant Serenity","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"공포와 폭력이 벌어지는 가운데 한 인물이 미소와 차분함을 유지해 기묘한 대비를 만든다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-007494/index.html"},{"id":"MEJE-KW-007495","row_version":1,"title":"구매자를 쫓아내려는 방해","original":"Dissuading the Property Buyer","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"팔려는 집에 살고 싶은 인물이 집 상태를 일부러 나빠 보이게 해 잠재 구매자가 마음을 접게 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007495/index.html"},{"id":"MEJE-KW-007496","row_version":1,"title":"여성판 대응 인물","original":"Distaff Counterpart","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"기존 남성 인물과 비슷한 능력·역할·설정을 지닌 여성 인물을 새로 만든다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007496/index.html"},{"id":"MEJE-KW-007497","row_version":1,"title":"시사 사건과의 연상을 피한 수정","original":"Distanced from Current Events","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"현실의 비극이나 큰 사건과 작품의 장면이 겹치자 제작자가 연상과 상처를 줄이기 위해 내용을 바꾼다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007497/index.html"},{"id":"MEJE-KW-007498","row_version":1,"title":"멀리 떨어진 두 사람의 이중창","original":"Distant Duet","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"서로 다른 장소에 있는 두 인물이 같은 노래를 함께 부르며 물리적 거리와 감정의 연결을 동시에 보여 준다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-007498/index.html"},{"id":"MEJE-KW-007499","row_version":2,"title":"먼 훗날의 결말","original":"Distant Finale","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"주요 사건이 끝난 뒤 오랜 시간이 흐른 모습을 보여 주어 인물과 세계의 이후 변화를 정리한다. 먼 과거의 짧은 서막은 본편 이전의 먼 시간을, 먼 훗날의 결말은 본편 이후의 먼 시간을 보여 준다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007499/index.html"},{"id":"MEJE-KW-007500","row_version":1,"title":"멀리서 지켜보는 조문객","original":"Distant Funeral Attendee","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"장례식에 함께할 수 없는 인물이 떨어진 곳에서 조용히 참석해 고인과의 숨은 관계를 드러낸다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007500/index.html"},{"id":"MEJE-KW-007501","row_version":1,"title":"먼 과거의 짧은 서막","original":"Distant Prologue","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"본편보다 훨씬 이전 시대의 사건을 짧게 보여 준 뒤 시간이 흘러 본 이야기를 시작한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007501/index.html"},{"id":"MEJE-KW-007502","row_version":1,"title":"먼 곳에서 본 사건의 반응","original":"Distant Reaction Shot","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"거대한 사건 직후 화면을 멀리 떨어진 곳으로 옮겨 그곳에서도 충격이 감지됨을 보여 준다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007502/index.html"},{"id":"MEJE-KW-007503","row_version":3,"title":"먼 시대를 배경으로 한 후속작","original":"Distant Sequel","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"전작보다 수십 년 또는 수세대 뒤의 시대를 그려 앞선 사건이 역사나 전설이 된 모습을 보여 준다. 먼 훗날의 결말이 한 작품의 미래를 보여 준다면 먼 시대를 배경으로 한 후속작은 다음 작품 전체를 그 시대로 옮긴다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-007503/index.html"},{"id":"MEJE-KW-007504","row_version":1,"title":"두 장의 개성이 다른 더블 앨범","original":"Distinct Double Album","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"함께 발매된 두 음반이 단순한 분량 확장이 아니라 서로 다른 시대, 주제, 소리로 구분된다. 나란한 구성이 음악가의 여러 모습을 보여 준다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-007504/index.html"},{"id":"MEJE-KW-007505","row_version":2,"title":"다르다고 말하지만 같은 뜻","original":"Distinction Without a Difference","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 어떤 표현을 부정한 뒤 실제로는 같은 뜻인 말을 더 화려하게 바꾸어 쓴다. 말의 차이가 의미의 차이를 만들지 못한다는 점이 농담이 된다. 의미 차이 없는 말의 정정이 위급한 순간에 이어지면 위급한 순간의 불필요한 용어 정정의 웃음을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007505/index.html"},{"id":"MEJE-KW-007506","row_version":2,"title":"서로 구별되는 인물 외형","original":"Distinctive Appearances","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"여러 등장인물의 윤곽, 색, 옷차림을 충분히 다르게 설계해 관객이 누구인지 쉽게 알아보게 한다. 특히 비슷한 역할의 인물이 많은 작품에서 식별을 돕는다. 인물을 구분하기 쉬운 전체 디자인 안에는 인물을 알아보게 하는 몸의 표식 같은 작은 신체 단서도 쓰인다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007506/index.html"},{"id":"MEJE-KW-007507","row_version":1,"title":"품격을 암시하는 파이프","original":"Distinguished Gentleman's Pipe","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"파이프를 문 인물을 연륜 있고 침착하거나 지적인 사람처럼 보이게 하는 시각 기호다. 때로는 거만함까지 암시한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-007507/index.html"},{"id":"MEJE-KW-007508","row_version":1,"title":"인물을 알아보게 하는 몸의 표식","original":"Distinguishing Mark","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"특이한 흉터나 점처럼 변하지 않는 신체 특징이 인물 확인의 단서가 된다. 이름이나 얼굴이 가려져도 정체를 드러낼 수 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-007508/index.html"},{"id":"MEJE-KW-007509","row_version":2,"title":"주의를 돌려 무기 빼앗기","original":"Distract and Disarm","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"위협받던 인물이 상대의 주의를 잠깐 돌려 대치의 주도권을 바꾼다. 말과 행동의 시간차를 이용한 허구적 역전 장면이다. 눈길을 돌리기 위한 행동을 동료 사이의 다툼으로 꾸미면 시선을 끄는 가짜 싸움이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007509/index.html"},{"id":"MEJE-KW-007510","row_version":2,"title":"자기 외모에 한눈팔다","original":"Distracted by My Own Sexy","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 자신의 거울상이나 모습에 매료되어 원래 하려던 일을 잊는다. 자기애를 희극적으로 보여 주는 행동이다. 다른 사람의 외모가 아니라 자신의 모습에 홀린다는 점에서 매력적인 외모에 정신이 팔리다과 구분된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007510/index.html"},{"id":"MEJE-KW-007511","row_version":1,"title":"사치품에 넘어가 문제를 잊다","original":"Distracted by the Luxury","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"비싼 물건을 받자 앞서 화냈던 일까지 잊는 사람으로 여성을 묘사하는 관습이다. 성별과 소비 욕망을 단순하게 연결하는 고정관념을 드러낸다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007511/index.html"},{"id":"MEJE-KW-007512","row_version":1,"title":"매력적인 외모에 정신이 팔리다","original":"Distracted by the Sexy","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 다른 사람의 성적 매력에 주의를 빼앗겨 하던 일을 놓치거나 실수한다. 외모를 둘러싼 반응을 과장한 희극적 장면이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007512/index.html"},{"id":"MEJE-KW-007513","row_version":1,"title":"죽음도 모른 채 이어 가는 말","original":"Distracted from Death","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"곁에 있던 사람이 조용히 죽은 줄 모르고 인물이 그에게 계속 말을 건넨다. 늦게 찾아온 깨달음이 상실의 충격을 키운다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007513/index.html"},{"id":"MEJE-KW-007514","row_version":2,"title":"위급한 순간의 불필요한 용어 정정","original":"Distracting Disambiguation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"당장 행동해야 하는 상황에서 인물이 의미 전달에 지장 없는 명칭 차이를 굳이 바로잡는다. 정확함에 매달린 말이 긴박한 행동을 늦춘다. 굳이 고친 두 명칭이 실제로는 같다면 다르다고 말하지만 같은 뜻와 겹친다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007514/index.html"},{"id":"MEJE-KW-007515","row_version":1,"title":"시선을 끄는 가짜 싸움","original":"Distracting Fake Fight","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"동료끼리 실제로 다투는 척해 감시하는 사람의 눈길을 모은다. 겉으로 보이는 갈등이 다른 행동을 숨기는 미끼가 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007515/index.html"}]}.cards;